def max_count(banned: List[int], n: int, max_sum: int) -> int:
    """Walk the gaps between sorted banned values, taking smallest numbers first."""
    blocked = sorted(set(b for b in banned if b <= n))
    blocked.append(n + 1)          # sentinel closes the last gap
    chosen = 0
    lo = 1
    for b in blocked:
        hi = b - 1
        if lo <= hi:
            size = hi - lo + 1

            def cost(t: int) -> int:
                return t * lo + t * (t - 1) // 2

            if cost(size) <= max_sum:
                take = size
            else:
                left, right = 0, size
                while left < right:
                    mid = (left + right + 1) // 2
                    if cost(mid) <= max_sum:
                        left = mid
                    else:
                        right = mid - 1
                take = left
            chosen += take
            max_sum -= cost(take)
            if take < size:
                break
        lo = b + 1
    return chosen

