def maximum_length(nums: list[int], k: int) -> int:
    # best[j]: value -> longest good subsequence ending in that value with at most j changes
    best = [dict() for _ in range(k + 1)]
    # top[j]: the two largest (length, value) pairs of best[j], with distinct values
    top = [[(0, None), (0, None)] for _ in range(k + 1)]

    def record(j: int, value: int, length: int) -> None:
        if length <= best[j].get(value, 0):
            return
        best[j][value] = length
        first, second = top[j]
        if first[1] == value:
            top[j][0] = (length, value)
        elif length > first[0]:
            top[j] = [(length, value), first]
        elif length > second[0]:
            top[j][1] = (length, value)

    answer = 0
    for x in nums:
        new_lengths = []
        for j in range(k + 1):
            length = best[j].get(x, 0) + 1          # extend without a change
            if j > 0:
                first, second = top[j - 1]
                prev = second[0] if first[1] == x else first[0]
                length = max(length, prev + 1)      # extend with one change
            new_lengths.append(length)
        for j, length in enumerate(new_lengths):
            record(j, x, length)
            answer = max(answer, length)
    return answer

def can_reach(s: str, minJump: int, maxJump: int) -> bool:
    n = len(s)
    reach = [False] * n
    reach[0] = True
    inside = 0      # reachable indices within [j - maxJump, j - minJump]
    for j in range(1, n):
        if j - minJump >= 0 and reach[j - minJump]:
            inside += 1                       # enters the window
        if j - maxJump - 1 >= 0 and reach[j - maxJump - 1]:
            inside -= 1                       # leaves the window
        reach[j] = inside > 0 and s[j] == "0"
    return reach[n - 1]

class TreeAncestor:
    def __init__(self, n: int, parent: list[int]):
        self.levels = max(1, n.bit_length())
        # up[j][v] is the 2^j th ancestor of v, or -1
        self.up = [parent[:]]
        for _ in range(1, self.levels):
            prev = self.up[-1]
            self.up.append([prev[p] if p != -1 else -1 for p in prev])

    def getKthAncestor(self, node: int, k: int) -> int:
        j = 0
        while k and node != -1:
            if k & 1:
                if j >= self.levels:
                    return -1
                node = self.up[j][node]
            k >>= 1
            j += 1
        return node

