def deep_merge(obj1, obj2):
    if isinstance(obj1, dict) and isinstance(obj2, dict):
        merged = dict(obj1)
        for key, value in obj2.items():
            merged[key] = deep_merge(obj1[key], value) if key in obj1 else value
