class MyCalendarTwo:
    def __init__(self):
        self.events = []    # every accepted event
        self.doubles = []   # regions already covered by two events

    def book(self, startTime: int, endTime: int) -> bool:
        # Overlapping a double booked region would make a triple booking.
        for s, e in self.doubles:
            if s < endTime and startTime < e:
                return False
        # Record the new double booked regions this event creates.
        for s, e in self.events:
            if s < endTime and startTime < e:
                self.doubles.append((max(s, startTime), min(e, endTime)))
        self.events.append((startTime, endTime))
        return True

