def min_jumps(nums: list[int]) -> int:
    n = len(nums)
    if n == 1:
        return 0
    max_val = max(nums)

    # sieve of Eratosthenes for primality up to max_val
    is_prime = bytearray([1]) * (max_val + 1)
    is_prime[0] = 0
    if max_val >= 1:
        is_prime[1] = 0
    for p in range(2, math.isqrt(max_val) + 1):
        if is_prime[p]:
            is_prime[p * p::p] = bytearray(len(range(p * p, max_val + 1, p)))

    # indices grouped by value, so multiples of a prime can be looked up quickly
    by_value = defaultdict(list)
    for i, v in enumerate(nums):
        by_value[v].append(i)

    def group_for(p):
        # every index whose value is a multiple of p
        out = []
        for mult in range(p, max_val + 1, p):
            if mult in by_value:
                out.extend(by_value[mult])
        return out

    dist = [-1] * n
    dist[0] = 0
    queue = deque([0])
    expanded = set()          # primes whose teleport group was already used
    while queue:
        i = queue.popleft()
        d = dist[i]
        if i == n - 1:
            return d
        for j in (i - 1, i + 1):
            if 0 <= j < n and dist[j] == -1:
                dist[j] = d + 1
                queue.append(j)
        v = nums[i]
        if is_prime[v] and v not in expanded:
            expanded.add(v)
            for j in group_for(v):
                if dist[j] == -1:
                    dist[j] = d + 1
                    queue.append(j)
    return dist[n - 1]

def max_total_value(value: list[int], decay: list[int], m: int) -> int:
    MOD = 10**9 + 7

    def count_at_least(x):
        # number of yields (over all indices) that are >= x
        total = 0
        for v, d in zip(value, decay):
            if v >= x:
                total += (v - x) // d + 1
        return total

    def sum_at_least(x):
        # (count, sum) of all yields that are >= x
        cnt = total = 0
        for v, d in zip(value, decay):
            if v >= x:
                c = (v - x) // d + 1
                cnt += c
                total += c * v - d * c * (c - 1) // 2
        return cnt, total

    if count_at_least(1) <= m:
        return sum_at_least(1)[1] % MOD      # take every positive yield

    # largest threshold T with at least m yields >= T
    lo, hi = 1, max(value)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if count_at_least(mid) >= m:
            lo = mid
        else:
            hi = mid - 1
    T = lo
    taken, total = sum_at_least(T + 1)       # everything strictly above T
    total += (m - taken) * T                 # fill the rest with yields equal to T
    return total % MOD

