def find_shortest_path(master: "GridMaster") -> int:
    STEP = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
    BACK = {"U": "D", "D": "U", "L": "R", "R": "L"}

    # Phase 1: explore every reachable cell with an iterative DFS that
    # physically moves the robot and retraces its steps when backtracking.
    seen = {(0, 0)}
    target = (0, 0) if master.isTarget() else None
    # each frame: [cell, directions still to try, direction used to enter]
    stack = [[(0, 0), list("UDLR"), None]]
    while stack:
        cell, todo, came_by = stack[-1]
        if todo:
            d = todo.pop()
            nxt = (cell[0] + STEP[d][0], cell[1] + STEP[d][1])
            if nxt in seen or not master.canMove(d):
                continue
            master.move(d)
            seen.add(nxt)
            if master.isTarget():
                target = nxt
            stack.append([nxt, list("UDLR"), d])
        else:
            stack.pop()
            if came_by is not None:
                master.move(BACK[came_by])   # walk back to the parent cell

    if target is None:
        return -1

    # Phase 2: BFS over the discovered cells.
    dist = {(0, 0): 0}
    queue = deque([(0, 0)])
    while queue:
        cell = queue.popleft()
        if cell == target:
            return dist[cell]
        for dr, dc in STEP.values():
            nxt = (cell[0] + dr, cell[1] + dc)
            if nxt in seen and nxt not in dist:
                dist[nxt] = dist[cell] + 1
                queue.append(nxt)
    return -1

