def prev_perm_opt1(arr: list[int]) -> list[int]:
    n = len(arr)
    i = n - 2
    while i >= 0 and arr[i] <= arr[i + 1]:
        i -= 1                      # find the rightmost descent
    if i < 0:
        return arr                  # already the smallest reachable
    j = n - 1
    while arr[j] >= arr[i]:
        j -= 1                      # largest value smaller than arr[i]
    while arr[j - 1] == arr[j]:
        j -= 1                      # leftmost copy of that value
    arr[i], arr[j] = arr[j], arr[i]
    return arr

