            i, best = p - 1, 0
            while i > 0:
                if tree[i] > best:
                    best = tree[i]
                i -= i & -i
            out[idx] = best
            i, val = p, order_profits[idx]
            while i <= V:
                if tree[i] < val:
                    tree[i] = val
                i += i & -i
        return out

    left = prefix_best(prices, profits)
    # mirror prices so that a larger price becomes a smaller index
    right = prefix_best([V + 1 - p for p in reversed(prices)], profits[::-1])[::-1]

    answer = -1
    for j in range(n):
        if left[j] and right[j]:
            answer = max(answer, left[j] + profits[j] + right[j])
    return answer

def minimum_levels(possible: list[int]) -> int:
    n = len(possible)
    total = sum(1 if p else -1 for p in possible)
    alice = 0
    # Alice may take at most n - 1 levels so that Bob plays at least one.
    for k in range(n - 1):
        alice += 1 if possible[k] else -1
        if 2 * alice > total:
            return k + 1
    return -1
